INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422764-fin425', 'stk-almax', 'FIN 425', 'info', '{"desc": "سلام عليكم جميعا\n\nانا اخذت الكورس مع دكتور هشام مرداد سمستر 132\n\nجودة المقرر بشكل عام\nجودة المقرر جدا عالية و ترفع من كفائة الطالب بشكل ملحوظ\n\nb]المواضيع التي يغطيها المقرر\n\nالمواضيع التي يغطيها المقرر هي جميعها مواضيع درستها في المواد الي قبل بس في هالمادة يكووون تطبيق عملي بأستخدام برنامج الاكسل و راح تتعلم شغلات رهيبه في البرنامج.\n\nالكتاب المستخدم للمقرر\n\nما تحتاج الكتاب ابدا في هذي المادة\n\nالأسئلة والأمثلة المستخدمة في المقرر\nالاسئلة كلها في الاكسل و بالتركيز مع الدكتور في كيفية حل الاسئلة خلاص ما تحتاج تذاكر\n\nنصيحتي للي يبي يجيب فل مارك يذاكر شغلتين فقط: الاولد اكزام + الهوم ورك للدكتور هشام مرداد و يحول يحلهم بنفسه بدون اي مساعده من احد\n\nمدى فائدته في الناحية التطبيقية\n\nفائدة كبيره جدا من الناحية العلمية و العملية و الشخصية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fin-425-computer-application-in-finance/121024/3", "user": "almax", "ts": 1437288664000, "tid": 121024, "pn": 3}}', 1437288664000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504422-fin425', 'stk-user9840', 'FIN 425', 'info', '{"desc": "هذا الموضوع مخصص لمناقشة المقرر المذكور في العنوان\nبنود تساعد في تقييم المقرر:\n\nجودة المقرر بشكل عام\nالمواضيع التي يغطيها المقرر\nالكتاب المستخدم للمقرر\nالأسئلة والأمثلة المستخدمة في المقرر\nمدى فائدته في الناحية التطبيقية\n\nولكم الحرية في تقييم المقرر باستحداث بنود أخرى ترونها مناسبه لتقييمه.\n\nكما نرجو تحري الصدق والعدل في تقييم المقرر\nوعدم الخلط بين تقييم الأستاذ وتقييم المقرر بذاته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fin-425-financial-modeling/180798/1", "user": "user9840", "ts": 1546441113000, "tid": 180798, "pn": 1}}', 1546441113000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-fin425', 'stk-practice', 'FIN 425', 'doc', '{"docs": [{"id": "stk-dr-f107072", "n": "Dr. H.smaoui", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "FIN425 - TERM152\n\n- الدكتور طيب لكن مزاجي احيانا فلا تتاخر او تطلع الجوال\n- كل نهاية شابتر فيه واجب وعادة طويل وتسويه بالاكسل\n- المادة طول الوقت في اللاب وتحتاج تكون سريع وتشتغل مع الدكتور لانك ممكن تضيع بسهولة وما تفهم\n- مافي مياجر ولا كويزات ، هوموركات وبروجكت وفاينل\n- البروجكت طويل وشغله كثير وياخذ وقت ، لا تسويه اخر اسبوع بتتعب\n- الفاينل بشكل عام معقول ، لكن المشكلة الماتيريال كثير ويلخبطك فاستعد من بدري\n- بشكل عام الدكتور يعتبر كويس لكن لا تتوقع منه اي بونس يعني لو التوتال حقك 79 خلاص سي بلس وقلنا باخر ايميل Bargaining is not allowed وينزلها بالبورتال بنفس اليوم\n- طبعا قيمته رغم انه مشي من الجامعة بس لانه مشي قبل كم سنة ورجع فيمكن يرجع مرة ثانية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456240-fin425", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/h-smaoui/107072/2", "user": "Practice", "ts": 1472627693000, "tid": 107072, "pn": 2}}]}', 1472627693000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-fin425', 'stk-guest', 'FIN 425', 'doc', '{"docs": [{"id": "stk-dr-f176832", "n": "Dr. Qi Dong", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "**Fin425-Financial Modeling **\n172\n\nQi dong وما أدراك ما Qi dong\nأخذت معه Fin250 في 161 وFin425 في 172\n\nالتحضير: أول ثلاث أرباع الترم كان يحضر، لكنه وقف بالنهاية\nطريقة الشرح : لايمكن التنبؤ بها. أول الأيام بعض الأيام يجي يفتح الكمبيوتر ويفتح أي موضوع له علاقة بالـBusiness ويقعد يتكلم على اللي عنده قدام في الكلاس. أحياناً يجيب فكرة يبغانا نقلدها بالإكسل وتكون هي الأسايمنت.\nالكويزات: لا يوجد\nالمياجر: ميدتيرم صعب (راح أتكلم عنها في الإضافات)\nالفاينلات: سهل\nالقريد النهائي: F- ولو فيه أقل عطيته\nالصوت: ضعيف جداً ولا يسمعه إلا القريب منه، الأكسنت مش بذاك الوضوح\nإضافات:\n\n1- السيلابس مانزل إلا الأسبوع الرابع وكان كالآتي 30% أسايمنت 30%بروجكت 30% فاينل 10% حضور.\n\n2- لو تلاحظون مافيه ميدتيرم ولا مياجر ولا هم يحزنون. يبدو إن التشيرمان أجبره يحط ميد، الأسبوع السادس قرر يصير فيه ميدتيرم.\nفأرسل إعلان بالبلاكبورد إنه التاريخ كذا راح يكون فيه ميدتيرم. طبعاً منطقياً راح يتغير وزن الدرجات، لكننا لا نعرف حتى الآن وزن الدرجات كم!\n\n3- الميدتيرم صحح نصه خلال النص الأخير من الترم والباقي صححه مع الفاينل، زميل لي ما استلم درجة الميد حتى الآن.\n\n4- الفاينل كان يوم May5 اليوم May10 مانزل شيء… والغالب أنه رايح ينزل الدرجات آخر يوم آخر ساعة عشان يتفادى النقاش.\n\n5-الرجل فوضوي إلى أبعد درجة، يتصدد عن الإيميل قدر الإمكان، ألغى كلاسات كثيرة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492119-fin425", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/qi-dong/176832/4", "user": "Guest", "ts": 1525976960000, "tid": 176832, "pn": 4}}]}', 1525976960000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
